A.antwort:
showDialog(
  context: context,
  builder: (BuildContext context) {
    return AlertDialog(
      title: Text('Fahrt beenden?'),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(false),
          child: Text('Nein'),
        ),
        TextButton(
          onPressed: () => Navigator.of(context).pop(true),
          child: Text('Ja'),
        ),
      ],
    );
  },
);
